import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Протокол mKCP","description":"","frontmatter":{},"headers":[],"relativePath":"ru/development/protocols/mkcp.md","filePath":"ru/development/protocols/mkcp.md","lastUpdated":1744252752000}`),a={name:`ru/development/protocols/mkcp.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="протокол-mkcp" tabindex="-1">Протокол mKCP <a class="header-anchor" href="#протокол-mkcp" aria-label="Permalink to “Протокол mKCP”">​</a></h1><p>mKCP - это потоковый транспортный протокол, основанный на <a href="https://github.com/skywind3000/kcp" target="_blank" rel="noreferrer">протоколе KCP</a>, который может передавать любые потоки данных по порядку.</p><h2 id="версия" tabindex="-1">Версия <a class="header-anchor" href="#версия" aria-label="Permalink to “Версия”">​</a></h2><p>Протокол mKCP не имеет номера версии, совместимость между версиями не гарантируется.</p><h2 id="зависимости" tabindex="-1">Зависимости <a class="header-anchor" href="#зависимости" aria-label="Permalink to “Зависимости”">​</a></h2><h3 id="базовыи-протокол" tabindex="-1">Базовый протокол <a class="header-anchor" href="#базовыи-протокол" aria-label="Permalink to “Базовый протокол”">​</a></h3><p>mKCP - это протокол, основанный на UDP, все коммуникации осуществляются по UDP.</p><h3 id="функции" tabindex="-1">Функции <a class="header-anchor" href="#функции" aria-label="Permalink to “Функции”">​</a></h3><ul><li>fnv: хэш-функция <a href="https://en.wikipedia.org/wiki/Fowler%E2%80%93Noll%E2%80%93Vo_hash_function" target="_blank" rel="noreferrer">FNV-1a</a><ul><li>Входные данные: строка произвольной длины;</li><li>Выходные данные: 32-битное беззнаковое целое число;</li></ul></li></ul><h2 id="процесс-коммуникации" tabindex="-1">Процесс коммуникации <a class="header-anchor" href="#процесс-коммуникации" aria-label="Permalink to “Процесс коммуникации”">​</a></h2><ol><li>mKCP разбивает поток данных на несколько пакетов для отправки. Каждый поток данных имеет уникальный идентификатор, который используется для различения разных потоков данных. Каждый пакет данных в потоке данных несет один и тот же идентификатор.</li><li>У mKCP нет процесса рукопожатия. При получении пакета данных определяется, является ли это новым вызовом или текущим вызовом, на основе идентификатора потока данных, который он несет.</li><li>Каждый пакет данных содержит несколько сегментов (Segment), которые делятся на три типа: данные (Data), подтверждение (ACK) и пульс (Ping). Каждый сегмент обрабатывается отдельно.</li></ol><h2 id="формат-данных" tabindex="-1">Формат данных <a class="header-anchor" href="#формат-данных" aria-label="Permalink to “Формат данных”">​</a></h2><h3 id="пакет-данных" tabindex="-1">Пакет данных <a class="header-anchor" href="#пакет-данных" aria-label="Permalink to “Пакет данных”">​</a></h3><table tabindex="0"><thead><tr><th>4 байта</th><th>2 байта</th><th>L байт</th></tr></thead><tbody><tr><td>Информация для аутентификации A</td><td>Длина данных L</td><td>Сегментная часть</td></tr></tbody></table><p>Где:</p><ul><li>Информация для аутентификации A = fnv(сегментная часть), big endian;</li><li>Сегментная часть может содержать несколько сегментов;</li></ul><h3 id="сегмент-данных" tabindex="-1">Сегмент данных <a class="header-anchor" href="#сегмент-данных" aria-label="Permalink to “Сегмент данных”">​</a></h3><table tabindex="0"><thead><tr><th>2 байта</th><th>1 байт</th><th>1 байт</th><th>4 байта</th><th>4 байта</th><th>4 байта</th><th>2 байта</th><th>Len байт</th></tr></thead><tbody><tr><td>Идентификатор Conv</td><td>Команда Cmd</td><td>Опция Opt</td><td>Временная метка Ts</td><td>Порядковый номер Sn</td><td>Неподтвержденный порядковый номер Una</td><td>Длина Len</td><td>Данные</td></tr></tbody></table><p>Где:</p><ul><li>Идентификатор Conv: идентификатор потока данных mKCP</li><li>Команда Cmd: константа 0x01</li><li>Опция Opt: возможные значения: <ul><li>0x00: пустая опция</li><li>0x01: другая сторона отправила все данные</li></ul></li><li>Временная метка Ts: время отправки текущего сегмента с удаленной стороны, big endian</li><li>Порядковый номер Sn: позиция сегмента данных в потоке данных, порядковый номер начального сегмента равен 0, каждый последующий сегмент увеличивается на 1</li><li>Неподтвержденный порядковый номер Una: минимальный Sn, который отправляется удаленным хостом и еще не получил подтверждение</li></ul><h3 id="сегмент-подтверждения" tabindex="-1">Сегмент подтверждения <a class="header-anchor" href="#сегмент-подтверждения" aria-label="Permalink to “Сегмент подтверждения”">​</a></h3><table tabindex="0"><thead><tr><th>2 байта</th><th>1 байт</th><th>1 байт</th><th>4 байта</th><th>4 байта</th><th>4 байта</th><th>2 байта</th><th>Len * 4 байта</th></tr></thead><tbody><tr><td>Идентификатор Conv</td><td>Команда Cmd</td><td>Опция Opt</td><td>Окно Wnd</td><td>Следующий порядковый номер для приема Sn</td><td>Временная метка Ts</td><td>Длина Len</td><td>Подтвержденные порядковые номера</td></tr></tbody></table><p>Где:</p><ul><li>Идентификатор Conv: идентификатор потока данных mKCP</li><li>Команда Cmd: константа 0x00</li><li>Опция Opt: как указано выше</li><li>Окно Wnd: максимальный порядковый номер, который может принять удаленный хост</li><li>Следующий порядковый номер для приема Sn: минимальный порядковый номер сегмента данных, который не получил удаленный хост</li><li>Временная метка Ts: временная метка последнего полученного сегмента данных удаленным хостом, может использоваться для расчета задержки</li><li>Подтвержденные порядковые номера: каждые 4 байта указывают, что данные с этим порядковым номером получены и подтверждены</li></ul><p>Комментарий:</p><ul><li>Удаленный хост ожидает получения данных с порядковыми номерами в диапазоне [Sn, Wnd)</li></ul><h3 id="сегмент-пульса" tabindex="-1">Сегмент пульса <a class="header-anchor" href="#сегмент-пульса" aria-label="Permalink to “Сегмент пульса”">​</a></h3><table tabindex="0"><thead><tr><th>2 байта</th><th>1 байт</th><th>1 байт</th><th>4 байта</th><th>4 байта</th><th>4 байта</th></tr></thead><tbody><tr><td>Идентификатор Conv</td><td>Команда Cmd</td><td>Опция Opt</td><td>Неподтвержденный порядковый номер Una</td><td>Следующий порядковый номер для приема Sn</td><td>Задержка Rto</td></tr></tbody></table><p>Где:</p><ul><li>Идентификатор Conv: идентификатор потока данных mKCP</li><li>Команда Cmd: возможные значения: <ul><li>0x02: удаленный хост принудительно завершает сеанс</li><li>0x03: обычный пульс</li></ul></li><li>Опция Opt: как указано выше</li><li>Неподтвержденный порядковый номер Una: тот же, что и Una в сегменте данных</li><li>Следующий порядковый номер для приема Sn: тот же, что и Sn в сегменте подтверждения</li><li>Задержка Rto: задержка, рассчитанная самим удаленным хостом</li></ul>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};